"""Original bilingual packaging guides, with source links for principles."""
SOURCES = {
    "ups": ("UPS — Shipping Dimensions and Weight", "https://es-us-filexfer.ups.com/us/en/support/shipping-support/shipping-dimensions-weight"),
    "fedex": ("FedEx — Essential Packaging Guide", "https://www.fedex.com/content/dam/fedex/apac-asia-pacific/downloads/fedex-essential-packaging-guide-en-apac.pdf"),
    "nist": ("NIST — SI Units", "https://www.nist.gov/pml/owm/metric-si/si-units"),
}

GUIDES = [
    {"slug":"ukur-luar-paket","sources":["ups","fedex"],"id":{"title":"Ukur sisi luar paket setelah ditutup","summary":"Dimensi untuk rencana pengiriman berasal dari kotak yang sudah dikemas, bukan ukuran produk atau ukuran katalog kotak.","sections":[("Mulai dari paket jadi","Rakit, isi, dan tutup kotak sebelum mengukur. Ukur titik terluar pada tiga arah yang saling tegak lurus. Lipatan, tonjolan, atau lapisan pelindung yang menambah ukuran harus ikut terlihat dalam catatan."),("Tentukan tiga sisi","Catat sisi terpanjang sebagai panjang; dua sisi lainnya sebagai lebar dan tinggi. Simpan angka asli beserta satuannya sebelum menerapkan aturan pembulatan jasa kirim. Bila bentuk berubah karena tekanan, gunakan ukuran kondisi paket yang akan diserahkan."),("Buat catatan ulang","Timbang paket lengkap, termasuk kotak, isi, dan bahan pelindung. Foto bersama penggaris dapat membantu audit internal, tetapi tidak menggantikan pengukuran jasa kirim.")],"example":"Kotak tertutup 32 × 24 × 18 cm mempunyai volume luar 13.824 cm³ atau 13,824 liter.","pitfall":"Jangan memasukkan ukuran produk 30 × 20 × 12 cm sebagai ukuran paket yang sudah diberi bantalan."},"en":{"title":"Measure the outside of a closed parcel","summary":"A shipping plan starts with the packed box, not the product or a box catalogue's nominal size.","sections":[("Start with the finished parcel","Assemble, fill and close the box before measuring. Measure the outermost points in three perpendicular directions. Include flaps, bulges and protection that increase its dimensions."),("Record three sides","Call the longest side length and the other two width and height. Keep the original numbers and units before applying any carrier rounding rule. If the shape changes under pressure, measure the parcel as it will be handed over."),("Keep a repeatable note","Weigh the complete parcel, including the box, contents and cushioning. A ruler photograph may help your internal audit but does not replace a carrier's measurement.")],"example":"A closed box measuring 32 × 24 × 18 cm has an external volume of 13,824 cm³, or 13.824 litres.","pitfall":"Do not substitute a 30 × 20 × 12 cm product's size for the cushioned outer parcel."}},
    {"slug":"ukuran-dalam-kotak","sources":["fedex"],"id":{"title":"Bedakan ukuran dalam dan ukuran luar kotak","summary":"Kapasitas isi dan dimensi pengiriman menjawab dua pertanyaan yang berbeda.","sections":[("Periksa spesifikasi kotak","Ukuran yang dijual sebagai ukuran kotak sering menunjukkan ruang dalam. Konfirmasi apakah label pemasok menyebut ukuran dalam atau luar; ketebalan dinding menimbulkan selisih."),("Pakai ukuran sesuai keputusan","Gunakan ukuran dalam untuk menguji apakah produk dan pelindung muat. Gunakan ukuran luar dari paket tertutup untuk menghitung volume pengiriman. Jangan menukar keduanya walaupun angka terlihat dekat."),("Uji kotak nyata","Sampel kotak dapat berubah setelah dirakit, apalagi bila bahan melengkung. Ukur satu kotak contoh dan simpan kedua set dimensi bila pengiriman berulang.")],"example":"Kotak berukuran dalam 30 × 22 × 16 cm bisa memiliki ukuran luar 31 × 23 × 17 cm; ukur contoh untuk mendapatkan angka sebenarnya.","pitfall":"Jangan mengklaim selisih dinding selalu satu sentimeter; contoh itu hanya ilustrasi."},"en":{"title":"Separate a box's inside and outside sizes","summary":"Content capacity and shipment dimensions answer different questions.","sections":[("Check the box specification","A listed box size often describes its internal space. Confirm whether the supplier means internal or external size; wall thickness creates a difference."),("Use the right set of numbers","Use inside measurements to test whether the object and protection fit. Use the closed parcel's outside measurements for shipment volume. Do not swap the two because they look close."),("Test a real box","A sample may change shape when assembled, especially if the material bows. Measure one assembled box and retain both sets of dimensions for repeat shipments.")],"example":"A box with 30 × 22 × 16 cm of inner space might measure 31 × 23 × 17 cm outside; measure a sample for the actual figures.","pitfall":"Do not assume every wall adds exactly one centimetre; that is only an illustration."}},
    {"slug":"volume-dan-liter","sources":["nist"],"id":{"title":"Ubah ukuran paket menjadi volume yang dapat diperiksa","summary":"Perkalian tiga sisi menghasilkan cm³; bagi 1.000 untuk liter.","sections":[("Samakan satuan","Ubah semua sisi menjadi sentimeter sebelum mengalikan. Volume = panjang × lebar × tinggi. Hasil dalam sentimeter kubik; satu liter sama dengan 1.000 sentimeter kubik."),("Pisahkan volume dari kapasitas","Volume luar adalah ruang geometris yang ditempati paket, bukan kapasitas isi. Dinding, bantalan, dan ruang kosong mengurangi bagian yang dapat diisi."),("Simpan angka perantara","Catat tiga sisi dan hasil perkalian agar orang lain bisa memeriksa. Dua paket dengan volume sama mungkin memiliki panjang terjauh yang berbeda, sehingga pemeriksaan batas bentuk tetap diperlukan.")],"example":"32 × 24 × 18 = 13.824 cm³ = 13,824 liter.","pitfall":"Jangan menuliskan 13.824 cm³ sebagai 13.824 liter; tanda ribuan dan desimal harus jelas."},"en":{"title":"Turn parcel dimensions into checkable volume","summary":"Multiply three sides for cubic centimetres; divide by 1,000 for litres.","sections":[("Use one unit","Convert all sides to centimetres first. Volume equals length times width times height. The result is cubic centimetres; one litre is 1,000 cubic centimetres."),("Distinguish volume from capacity","External volume is the geometric space occupied by a parcel, not its useful content capacity. Walls, cushioning and voids reduce internal space."),("Keep intermediate figures","Record the three sides and their product for review. Two parcels with equal volume can have different longest sides, so shape limits need a separate check.")],"example":"32 × 24 × 18 = 13,824 cm³ = 13.824 litres.","pitfall":"Do not label 13,824 cm³ as 13,824 litres; keep grouping and decimal separators clear."}},
    {"slug":"berat-dimensi","sources":["ups"],"id":{"title":"Pahami berat dimensi tanpa menebak tarif","summary":"Pembagi jasa kirim dapat berubah menurut layanan dan kontrak; masukkan nilai yang berlaku sendiri.","sections":[("Rumus dasar","Berat dimensi dalam kilogram = volume luar dalam cm³ dibagi pembagi dalam cm³/kg. Pembagi harus berasal dari ketentuan layanan dan tanggal yang benar. Situs ini tidak memilih angka baku."),("Bandingkan dengan berat nyata","Timbang paket lengkap dalam kilogram. Perbandingan antara berat nyata dan berat dimensi menunjukkan nilai yang mungkin relevan untuk penagihan, tetapi jasa kirim dapat memiliki aturan pembulatan, batas, dan pengecualian lain."),("Verifikasi sebelum transaksi","Periksa kalkulator atau tarif resmi untuk tujuan dan layanan yang dipakai. Alat Vijeron hanya menjelaskan aritmetika, tidak menghitung harga atau menjamin berat tagihan.")],"example":"Volume 13.824 cm³ dengan pembagi contoh 5.000 cm³/kg menghasilkan 2,7648 kg. Pembagi 5.000 di sini contoh masukan, bukan aturan universal.","pitfall":"Jangan membulatkan atau memilih pembagi tanpa melihat ketentuan jasa kirim yang tepat."},"en":{"title":"Understand dimensional weight without guessing rates","summary":"Carrier divisors vary by service and agreement; supply the applicable value yourself.","sections":[("Basic formula","Dimensional weight in kilograms equals external volume in cm³ divided by a divisor in cm³/kg. Take the divisor from the correct service terms and date. This site chooses no default."),("Compare actual weight","Weigh the complete parcel in kilograms. Comparing actual and dimensional weight highlights a figure that may matter for billing, but carriers can apply different rounding, limits and exceptions."),("Verify before purchase","Check the carrier's own calculator or tariff for the destination and service. Vijeron explains arithmetic, not prices or a guaranteed billable weight.")],"example":"A 13,824 cm³ parcel with an example divisor of 5,000 cm³/kg gives 2.7648 kg. The divisor is an example input, not a universal rule.","pitfall":"Do not round or choose a divisor without checking the relevant carrier's terms."}},
    {"slug":"pilih-ruang-pelindung","sources":["fedex"],"id":{"title":"Rencanakan ruang pelindung di setiap sisi","summary":"Tambahkan ruang pada dua sisi setiap arah sebelum membandingkan produk dengan kotak.","sections":[("Mulai dari ukuran barang","Ukur bentang terluar barang. Tentukan ruang pelindung per sisi berdasarkan bahan dan kerentanan barang; angka ini keputusan pengemas, bukan jaminan aman."),("Hitung kebutuhan dalam","Untuk tiap arah, kebutuhan ruang = ukuran barang + 2 × ruang per sisi. Bandingkan kebutuhan ini dengan ukuran dalam kotak, bukan ukuran luarnya."),("Lakukan uji fisik","Kecocokan geometris belum membuktikan ketahanan. Coba bahan pelindung nyata, lihat apakah isi bergeser, dan ikuti petunjuk jasa kirim untuk jenis barang tersebut.")],"example":"Barang 20 × 15 × 10 cm dengan ruang rencana 2 cm di setiap sisi membutuhkan ruang dalam setidaknya 24 × 19 × 14 cm dalam orientasi yang sama.","pitfall":"Jangan menganggap satu angka ruang cocok untuk semua barang rapuh atau berat."},"en":{"title":"Plan protective room on every side","summary":"Add clearance on both sides of each direction before comparing an object with a box.","sections":[("Measure the object","Measure the object's outermost span. Choose clearance per side based on the material and vulnerability; this is the packer's decision, not a safety guarantee."),("Calculate required inner space","For each direction, required space equals object size plus twice the per-side clearance. Compare that need with the box's inside size, not outside size."),("Perform a physical trial","Geometric fit does not prove protection. Try the real cushioning, check whether the contents move and follow carrier guidance for the type of item.")],"example":"A 20 × 15 × 10 cm object with 2 cm planned clearance on each side needs at least 24 × 19 × 14 cm inside in the same orientation.","pitfall":"Do not assume one clearance works for every fragile or heavy object."}},
    {"slug":"rotasi-dan-kecocokan","sources":["fedex"],"id":{"title":"Uji orientasi barang dalam kotak","summary":"Kotak mungkin cocok setelah barang diputar, tetapi orientasi aman tetap perlu diputuskan manusia.","sections":[("Periksa orientasi tetap","Bandingkan panjang, lebar, dan tinggi kebutuhan barang dengan tiga ukuran dalam kotak pada urutan yang sama. Semua sisi harus tidak melebihi ruang yang tersedia."),("Coba rotasi siku-siku","Bila barang boleh diputar, uji enam permutasi tiga dimensi. Alat kecocokan kotak melakukan uji geometris ini; bentuk tak beraturan, pegangan, dan kemasan fleksibel tidak dimodelkan."),("Tinjau tanda arah","Botol, cairan, benda dengan komponen bergerak, atau barang bertanda sisi atas mungkin hanya boleh pada orientasi tertentu. Matikan rotasi pada alat bila diperlukan dan ikuti instruksi penanganan yang berlaku.")],"example":"Kebutuhan 24 × 19 × 14 cm tidak muat pada kotak 20 × 25 × 15 cm dalam urutan awal, tetapi muat setelah dua sisi pertama ditukar.","pitfall":"Jangan memutar barang yang mensyaratkan posisi tegak hanya agar angka tampak muat."},"en":{"title":"Test object orientation inside a box","summary":"A rotated item may fit geometrically, but a person must decide whether that orientation is safe.","sections":[("Check fixed orientation","Compare the object's required length, width and height with the box's three internal sides in the same order. Every requirement must be no greater than its available side."),("Try right-angle rotations","If rotation is permitted, test all six permutations of three dimensions. The box-fit tool checks this geometry; irregular shapes, handles and flexible packaging are not modelled."),("Respect orientation marks","Bottles, liquids, moving components and items marked upright may require one position. Turn rotation off in the tool when needed and follow applicable handling instructions.")],"example":"A 24 × 19 × 14 cm requirement fails in a 20 × 25 × 15 cm box in its initial order but fits after exchanging the first two axes.","pitfall":"Do not rotate an item that must stay upright just to make the numbers fit."}},
    {"slug":"panjang-dan-keliling","sources":["ups"],"id":{"title":"Catat panjang terjauh dan keliling paket","summary":"Volume saja tidak menggambarkan bentuk; panjang serta keliling sering diperiksa terpisah.","sections":[("Urutkan sisi luar","Ambil sisi luar terpanjang sebagai panjang. Jumlah dua sisi lainnya, masing-masing dikalikan dua, adalah keliling melintang atau girth."),("Hitung gabungannya","Panjang + keliling = sisi terpanjang + 2 × (dua sisi lain). Simpan angka ini sebagai pemeriksaan bentuk. Ambang dan definisi penerimaan paket tergantung layanan dan lokasi."),("Periksa batas terbaru","Sebelum mengirim paket panjang atau besar, baca aturan resmi jasa kirim untuk produk yang dipilih. Situs ini tidak menampilkan batas tetap karena syarat dapat berubah.")],"example":"Untuk 32 × 24 × 18 cm, panjang 32 cm, keliling 2 × (24 + 18) = 84 cm, dan panjang + keliling = 116 cm.","pitfall":"Jangan menganggap volume kecil berarti setiap bentuk otomatis diterima."},"en":{"title":"Record a parcel's longest side and girth","summary":"Volume does not describe shape; length and girth are often assessed separately.","sections":[("Sort the outer sides","Use the longest external side as length. Twice each of the other two sides added together is the transverse girth."),("Calculate the sum","Length plus girth equals the longest side plus twice the other two sides. Keep this as a shape check. Acceptance thresholds and definitions depend on the service and location."),("Check current limits","Before shipping a long or large parcel, read the official carrier terms for the selected product. This site gives no fixed limit because terms can change.")],"example":"For 32 × 24 × 18 cm, length is 32 cm, girth is 2 × (24 + 18) = 84 cm, and their sum is 116 cm.","pitfall":"Do not assume a small volume means every shape is automatically accepted."}},
    {"slug":"lembar-rencana-kemas","sources":["ups","fedex"],"id":{"title":"Buat lembar rencana kemasan yang dapat diaudit","summary":"Simpan ukuran, pilihan pelindung, dan ketentuan layanan sebagai satu catatan sebelum membuat label.","sections":[("Identifikasi barang dan kotak","Tulis ukuran barang, ruang pelindung per sisi, ukuran dalam kotak, serta alasan orientasi. Beri tanggal agar catatan tidak tercampur dengan versi kemasan sebelumnya."),("Ukur setelah ditutup","Catat tiga ukuran luar dan berat nyata paket lengkap. Hitung volume, panjang terjauh, keliling, serta berat dimensi hanya jika pembagi layanan diketahui."),("Uji dan verifikasi","Lakukan uji fisik bahan pelindung; cocokkan pembagi, aturan pembulatan, batas bentuk, dan tarif pada layanan resmi. Simpan tautan atau dokumen syarat yang dipakai bersama hasil perhitungan.")],"example":"Catatan contoh: barang 20 × 15 × 10 cm; ruang 2 cm/sisi; kebutuhan 24 × 19 × 14 cm; kotak dalam 25 × 20 × 15 cm; ukur ukuran luar setelah kotak ditutup.","pitfall":"Jangan hanya menyimpan satu angka berat dimensi tanpa dimensi, pembagi, dan tanggal aturan asal."},"en":{"title":"Make an auditable packaging plan","summary":"Keep dimensions, cushioning choices and service rules together before creating a label.","sections":[("Identify item and box","Write down item dimensions, planned per-side clearance, box inner dimensions and the reason for its orientation. Date the note so it does not get confused with an earlier packing version."),("Measure after closing","Record the packed parcel's three outside sides and actual mass. Calculate volume, longest side, girth and dimensional weight only if the service divisor is known."),("Test and verify","Physically test the cushioning; verify the divisor, rounding rules, shape limits and price in the carrier's official service. Keep the relevant terms link or document with the result.")],"example":"Example note: object 20 × 15 × 10 cm; clearance 2 cm/side; need 24 × 19 × 14 cm; box inner size 25 × 20 × 15 cm; measure outside after closing.","pitfall":"Do not keep only a dimensional-weight figure without the dimensions, divisor and date of the rule behind it."}},
]
